 { TCocoaCustomControl }

+function TCocoaCustomControl.accessibilityChildren: NSArray;
+begin
+   // NSControl does not enumerate child views by default. LCL uses this
+   // class as the document/panel container, so expose its unignored children.
+   Result := NSAccessibilityUnignoredChildren(subviews);
